def solve(n, k):
    if k == 0:
        return list(range(1, n + 1))

    perm = list(range(n, n - k - 1, -1))
    remaining = list(range(1, n - k))
    perm.extend(remaining)

    return perm

def main():
    n, k = map(int, input().split())
    result = solve(n, k)
    print(*result)

if __name__ == "__main__":
    main()

